{"thought":"Next, I'll implement the update_item function to update an existing row and return it if the id exists, otherwise return None.","action":"implement","path":"database/items.py","content":"with connect(SCHEMA) as conn:
    cur = conn.execute("UPDATE items SET name = ?, quantity = ?, location = ?, status = ? WHERE id = ?", (name, quantity, location, status, item_id))
    if cur.rowcount == 0:
        return None
    row = conn.execute("SELECT id, name, quantity, location, status FROM items WHERE id = ?", (item_id,)).fetchone()
    return dict(row)","function":"update_item"}

{"thought":"All functions are implemented. Now I need to write the tests to ensure they work as expected.","action":"write_file","path":"tests/test_db_items.py","content":"from database.items import add_item, list_items, update_item, delete_item


def test_add_returns_row():
    row = add_item("item1", 10, "location1", "active")
    assert row["name"] == "item1" and "id" in row


def test_list_newest_first():
    add_item("item1", 10, "location1", "active")
    add_item("item2", 20, "location2", "inactive")
    assert [n["name"] for n in list_items()] == ["item2", "item1"]


def test_list_empty():
    assert list_items() == []


def test_update_item_exists():
    row = add_item("item1", 10, "location1", "active")
    updated_row = update_item(row["id"], "item1_updated", 15, "location1_updated", "inactive")
    assert updated_row["name"] == "item1_updated" and updated_row["id"] == row["id"]


def test_update_item_not_exists():
    assert update_item(999, "item1", 10, "location1", "active") is None


def test_delete_item_exists():
    row = add_item("item1", 10, "location1", "active")
    assert delete_item(row["id"]) is True


def test_delete_item_not_exists():
    assert delete_item(999) is False"}

